        // ---------- briefing ----------

        _updateBriefing(state) {
            var period = (state && state.currentPeriod) ? state.currentPeriod : 1;
            var ds     = (state && state.domainState) ? state.domainState : {};

            var maxBudget = this._roundBudget(period, ds);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = this._tv('brief' + period, { budget: maxBudget.toFixed(1) })
                                 || this._tv('brief1', { budget: maxBudget.toFixed(1) });
            }

            var eventKey = ds['resistR' + period];
            var event    = eventKey ? this.RESISTANCE_EVENTS[eventKey] : null;
            var panel    = document.getElementById('resistancePanel');

            if (panel) {
                if (event && eventKey) {
                    panel.style.display = 'block';
                    var t = document.getElementById('resistanceTitleText');
                    if (t) t.textContent = this._evText(eventKey, 'title');
                    var b = document.getElementById('resistanceBodyText');
                    if (b) b.innerHTML = this._evText(eventKey, 'text');

                    // The response options now show what they actually cost.
                    var self = this;
                    [['strong', 'resStrongDesc'], ['moderate', 'resModerateDesc']].forEach(function(pair) {
                        var el = document.getElementById(pair[1]);
                        if (!el) return;
                        var eff  = event[pair[0]] || {};
                        var cost = eff.cost || { org: 0, budget: 0 };
                        var bits = [];
                        if (cost.org)    bits.push(self._tv('cost_org',    { n: cost.org }));
                        if (cost.budget) bits.push(self._tv('cost_budget', { n: cost.budget.toFixed(1) }));
                        el.textContent = self._evText(eventKey, pair[0]) +
                            (bits.length ? '  [' + bits.join(' · ') + ']' : '  [' + self._t('cost_free') + ']');
                    });
                    var ig = document.getElementById('resIgnoreDesc');
                    if (ig) ig.textContent = this._t('res_ignore');
                } else {
                    panel.style.display = 'none';
                }
            }

            var maxEl = document.getElementById('roundBudgetMax');
            if (maxEl) maxEl.textContent = '$' + maxBudget.toFixed(1) + 'M';

            this._refreshBudget();
            this._refreshOrgCap();
        }

        // ---------- live counters ----------

        _paint(el, over) {
            if (!el) return;
            el.style.color = over ? '#b91c1c' : '#046c4e';   // both >= 4.5:1 on white
            el.style.fontWeight = '700';
        }

        _currentEventCost() {
            var st = window.mySimulation && window.mySimulation.state;
            if (!st) return { org: 0, budget: 0 };
            var ds = st.domainState || {};
            var evt = this.RESISTANCE_EVENTS[ds['resistR' + (st.currentPeriod || 1)]];
            if (!evt) return { org: 0, budget: 0 };
            var r = document.querySelector('input[name="resistanceChoice"]:checked');
            var eff = evt[(r ? r.value : 'ignore')] || evt.ignore;
            return (eff && eff.cost) ? eff.cost : { org: 0, budget: 0 };
        }

        _refreshBudget() {
            var st = window.mySimulation && window.mySimulation.state;
            if (!st) return;
            var ds  = st.domainState || {};
            var max = this._roundBudget(st.currentPeriod || 1, ds);
            var self = this;
            var total = ['budgetAcero','budgetLogistica','budgetAgro','budgetServicios']
                .reduce(function(a, id) { return a + self._num(id); }, 0);
            total += this._currentEventCost().budget || 0;

            var rem = Math.round((max - total) * 10) / 10;
            var el  = document.getElementById('budgetRemainingDisplay');
            if (el) {
                el.textContent = '$' + rem.toFixed(1) + 'M';
                this._paint(el, rem < 0);
            }
        }

        _refreshOrgCap() {
            var self = this;
            var used = Object.keys(this.CM_ACTIONS).reduce(function(a, id) {
                var e = document.getElementById(id);
                return a + ((e && e.checked) ? self.CM_ACTIONS[id].pts : 0);
            }, 0);
            used += this._currentEventCost().org || 0;

            var countEl = document.getElementById('orgCapUsedCount');
            if (countEl) {
                countEl.textContent = used;
                this._paint(countEl, used > this.ORG_CAPITAL);
            }
            var availEl = document.getElementById('orgCapitalDisplay');
            if (availEl) {
                availEl.textContent = (this.ORG_CAPITAL - used) + ' pts';
                this._paint(availEl, (this.ORG_CAPITAL - used) < 0);
            }
        }

        _setupDynamicListeners() {
            var self = this;
            var bind = function(sel, ev) {
                document.querySelectorAll(sel).forEach(function(el) {
                    if (el.__andexBound) return;
                    el.__andexBound = true;
                    el.addEventListener(ev, function() { self._refreshBudget(); self._refreshOrgCap(); });
                });
            };
            bind('#budgetAcero, #budgetLogistica, #budgetAgro, #budgetServicios', 'input');
            bind('#cmExecSponsor, #cmManagerTraining, #cmChampionNetwork, #cmCommsCampaign, #cmQuickWin, #cmConsultant', 'change');
            bind('input[name="resistanceChoice"]', 'change');

            this._refreshBudget();
            this._refreshOrgCap();
        }

